import React, { useEffect, useState } from 'react';
import DashboardLayout from '../../components/layout/DashboardLayout';
import { eventAPI } from '../../utils/api';
import { getSocket, SOCKET_EVENTS } from '../../utils/socket';
import './StudentEvents.css';

const NAV_ITEMS = [
  { path: '/student', label: 'Dashboard', icon: '🏠', end: true },
  { path: '/student/submit', label: 'Submit Request', icon: '➕' },
  { path: '/student/requests', label: 'My Requests', icon: '📋' },
  { path: '/student/events', label: 'Events', icon: '📅' },
  { path: '/student/policies', label: 'Policies', icon: '📚' },
  { path: '/student/profile', label: 'Profile', icon: '👤' },
];

const CATEGORY_OPTIONS = ['', 'academic', 'club', 'placement', 'admin'];

export default function StudentEvents() {
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [category, setCategory] = useState('');
  const [search, setSearch] = useState('');
  const [registeringId, setRegisteringId] = useState('');
  const [selectedEvent, setSelectedEvent] = useState(null);

  const fetchEvents = async () => {
    setLoading(true);
    try {
      const data = await eventAPI.getEvents({ category, search, upcoming: true });
      setEvents(data);
      setError('');
      return data;
    } catch (requestError) {
      setError(requestError.message || 'Failed to load events');
      return [];
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchEvents().finally(() => setLoading(false));
  }, [category, search]);

  useEffect(() => {
    const intervalId = setInterval(() => {
      fetchEvents();
    }, 15000);

    return () => {
      clearInterval(intervalId);
    };
  }, [category, search]);

  useEffect(() => {
    const socket = getSocket();
    if (!socket) {
      return undefined;
    }

    const refreshEvents = () => {
      fetchEvents();
    };

    socket.on(SOCKET_EVENTS.EVENT_CREATED, refreshEvents);
    socket.on(SOCKET_EVENTS.EVENT_UPDATED, refreshEvents);

    return () => {
      socket.off(SOCKET_EVENTS.EVENT_CREATED, refreshEvents);
      socket.off(SOCKET_EVENTS.EVENT_UPDATED, refreshEvents);
    };
  }, [category, search]);

  const handleRegister = async (eventId) => {
    setRegisteringId(eventId);
    try {
      await eventAPI.registerForEvent(eventId);
      const refreshedEvents = await fetchEvents();
      setError('');
      if (selectedEvent && selectedEvent._id === eventId) {
        const latest = refreshedEvents.find((eventItem) => eventItem._id === eventId);
        if (latest) {
          setSelectedEvent(latest);
        }
      }
    } catch (requestError) {
      setError(requestError.message || 'Failed to register for event');
    }
    setRegisteringId('');
  };

  const openEventModal = (eventItem) => {
    setSelectedEvent(eventItem);
  };

  const closeEventModal = () => {
    setSelectedEvent(null);
  };

  return (
    <DashboardLayout navItems={NAV_ITEMS}>
      <div className="page-header">
        <h1 className="page-title">Upcoming Events</h1>
        <p className="page-subtitle">Register for academic, club, placement, and administrative events.</p>
      </div>

      {error && <div className="alert alert-error">❌ {error}</div>}

      <div className="card event-filter-card">
        <input
          className="form-input"
          placeholder="Search by title or location..."
          value={search}
          onChange={(event) => setSearch(event.target.value)}
        />
        <select className="form-select" value={category} onChange={(event) => setCategory(event.target.value)}>
          {CATEGORY_OPTIONS.map((option) => (
            <option key={option || 'all'} value={option}>
              {option ? option[0].toUpperCase() + option.slice(1) : 'All categories'}
            </option>
          ))}
        </select>
      </div>

      {loading ? (
        <div className="card">
          <div className="empty-state">
            <div className="spinner" style={{ marginBottom: 16 }} />
            <h3>Loading events...</h3>
          </div>
        </div>
      ) : events.length === 0 ? (
        <div className="card">
          <div className="empty-state">
            <h3>No upcoming events found</h3>
          </div>
        </div>
      ) : (
        <div className="event-grid">
          {events.map((eventItem) => (
            <div
              key={eventItem._id}
              className="card event-card event-card-clickable"
              onClick={() => openEventModal(eventItem)}
              role="button"
              tabIndex={0}
              onKeyDown={(event) => {
                if (event.key === 'Enter') {
                  openEventModal(eventItem);
                }
              }}
            >
              {eventItem.poster?.url && (
                <img
                  src={eventItem.poster.url}
                  alt={`${eventItem.title} poster`}
                  className="event-poster-image"
                />
              )}
              <div className="event-card-header">
                <div className="event-category">{eventItem.category}</div>
                <div className="event-status">{eventItem.status}</div>
              </div>
              <h3 className="event-title">{eventItem.title}</h3>
              <p className="event-description">{eventItem.description}</p>
              <div className="event-meta">📍 {eventItem.location}</div>
              <div className="event-meta">🕒 {new Date(eventItem.startAt).toLocaleString('en-GB')}</div>
              <div className="event-meta">
                👥 {eventItem.attendeeCount}/{eventItem.capacity} registered
              </div>
              <div className="event-meta">
                ⏱ Seats left: {eventItem.seatsAvailable}
              </div>
              {eventItem.registrationDeadline && (
                <div className="event-meta">
                  Registration closes: {new Date(eventItem.registrationDeadline).toLocaleString('en-GB')}
                </div>
              )}
              <div className="event-actions">
                <button
                  className="btn btn-primary btn-sm"
                  onClick={(event) => {
                    event.stopPropagation();
                    handleRegister(eventItem._id);
                  }}
                  disabled={eventItem.isRegistered || registeringId === eventItem._id || eventItem.seatsAvailable <= 0}
                >
                  {eventItem.isRegistered ? 'Registered' : registeringId === eventItem._id ? 'Registering...' : 'Register'}
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {selectedEvent && (
        <div className="event-modal-overlay" onClick={closeEventModal}>
          <div className="event-modal-card" onClick={(event) => event.stopPropagation()}>
            <button className="event-modal-close" onClick={closeEventModal}>X</button>
            {selectedEvent.poster?.url && (
              <img
                src={selectedEvent.poster.url}
                alt={`${selectedEvent.title} poster`}
                className="event-modal-poster"
              />
            )}
            <div className="event-card-header">
              <div className="event-category">{selectedEvent.category}</div>
              <div className="event-status">{selectedEvent.status}</div>
            </div>
            <h2 className="event-title">{selectedEvent.title}</h2>
            <p className="event-description">{selectedEvent.description}</p>
            <div className="event-meta">📍 {selectedEvent.location}</div>
            <div className="event-meta">🕒 {new Date(selectedEvent.startAt).toLocaleString('en-GB')}</div>
            <div className="event-meta">👥 {selectedEvent.attendeeCount}/{selectedEvent.capacity} registered</div>
            <div className="event-meta">⏱ Seats left: {selectedEvent.seatsAvailable}</div>
            {selectedEvent.registrationDeadline && (
              <div className="event-meta">
                Registration closes: {new Date(selectedEvent.registrationDeadline).toLocaleString('en-GB')}
              </div>
            )}
            <div className="event-actions">
              <button
                className="btn btn-primary"
                onClick={() => handleRegister(selectedEvent._id)}
                disabled={selectedEvent.isRegistered || registeringId === selectedEvent._id || selectedEvent.seatsAvailable <= 0}
              >
                {selectedEvent.isRegistered ? 'Registered' : registeringId === selectedEvent._id ? 'Registering...' : 'Register'}
              </button>
            </div>
          </div>
        </div>
      )}
    </DashboardLayout>
  );
}
